#include <stddef.h>
#include <stdint.h>
#define BAD (-1.0e300)
double jaro_similarity(const int64_t*v,size_t n){if(!v||n<2||n>66)return BAD;int64_t n1=v[0];if(n1<0||n1>32||1+(size_t)n1>=n)return BAD;size_t p2=1+(size_t)n1;int64_t n2=v[p2];if(n2<0||n2>32||n1<n2||n!=p2+1+(size_t)n2)return BAD;for(size_t i=0;i<(size_t)n1;i++)if(v[1+i]<0||v[1+i]>127)return BAD;for(size_t j=0;j<(size_t)n2;j++)if(v[p2+1+j]<0||v[p2+1+j]>127)return BAD;int64_t s1[32],s2[32];for(size_t i=0;i<(size_t)n1;i++)s1[i]=v[1+i];for(size_t j=0;j<(size_t)n2;j++)s2[j]=v[p2+1+j];if(n1==n2){int equal=1;for(size_t i=0;i<(size_t)n1;i++)if(s1[i]!=s2[i])equal=0;if(equal)return 1.0;}int radius=(int)(n1/2)-1;if(radius<0)radius=0;int m1[32]={0},m2[32]={0},matches=0;for(int i=0;i<n1;i++){int start=i-radius;if(start<0)start=0;int end=i+radius;if(end>=n2)end=(int)n2-1;for(int j=start;j<=end;j++)if(s1[i]==s2[j]&&!m2[j]){matches++;m1[i]=1;m2[j]=1;break;}}if(!matches)return 0.0;int trans=0,j=0;for(int i=0;i<n1;i++)if(m1[i]){while(!m2[j])j++;if(s1[i]!=s2[j])trans++;j++;}trans/=2;return ((double)matches/n1+(double)matches/n2+(double)(matches-trans)/matches)/3.0;}
